/* Only Vocabulary Sprint uses the forest race. Teacher-edited questions are retained. */
(()=>{const original=renderGame,oldShow=show;show=function(view){document.body.classList.remove('forest-race');const frame=document.querySelector('#forest-race-frame');if(view!=='player')frame?.remove();return oldShow(view);};renderGame=function(){if(game?.lesson.id!=='english-7-quiz')return original();document.body.classList.add('forest-race');$('#play-title').textContent=game.lesson.title;$('#play-format').textContent='Forest Trail · Solo race';$('#play-subtitle').textContent='Grade 7 · English';if(!$('#forest-race-frame')){const frame=document.createElement('iframe');frame.id='forest-race-frame';frame.title='Vocabulary Sprint Forest Trail';frame.src='./vocabulary-sprint/index.html';frame.onload=()=>frame.contentWindow.postMessage({vocabularyItems:game.items},location.origin);$('#arena').replaceChildren(frame);}else $('#forest-race-frame').contentWindow.postMessage({vocabularyItems:game.items},location.origin);};const css=document.createElement('style');css.textContent='.forest-race .arcade-mission,.forest-race .arcade-controls,.forest-race #scoreboard,body.forest-race #player #game-canvas,.forest-race .play-heading,.forest-race .player-bottom{display:none!important}.forest-race #arena{padding:0;background:none;border:0;box-shadow:none}.forest-race #forest-race-frame{width:100%;height:calc(100vh - 110px);min-height:720px;border:0;border-radius:18px}.forest-race #player{max-width:1440px}';document.head.append(css);})();
